import * as THREE from 'three/webgpu';
import { float, vec3, normalize, positionView, normalWorld, add, mix, step, length, dot, emissive, output } from 'three/tsl';
import gsap from 'gsap';

/**
 * Creates a badge for the journal hub – a small capsule label with accent edge light.
 * @param {import('@/types').NodeConfig} config
 * @param {import('@/types').NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // --- Load GLB mesh (cached) ---
  const glbGroup = ctx.glbLoader.load(config.meshUrl);
  const meshGroup = glbGroup.clone(true);
  const mesh = meshGroup.children[0]; // assume single mesh

  // --- Apply scene placement ---
  const { x, y, z } = config.scenePlacement.position;
  const { x: rx, y: ry, z: rz } = config.scenePlacement.rotation;
  const { x: sx, y: sy, z: sz } = config.scenePlacement.scale;
  meshGroup.position.set(x, y, z);
  meshGroup.rotation.set(rx, ry, rz);
  meshGroup.scale.set(sx, sy, sz);

  // --- Accent edge light (rim) via TSL NodeMaterial ---
  if (mesh.material) {
    const origMat = mesh.material;
    const rimPower = float(2.0);
    const rimIntensity = float(0.4);
    const viewDir = normalize(positionView.negate());
    const rim = step(0.3, rimPower.pow(1.0 - dot(viewDir, normalize(normalWorld))));
    const accentColor = new THREE.Color(config.visual.colors.accent);
    const rimEmissive = emissive(vec3(accentColor.r, accentColor.g, accentColor.b).mul(rim).mul(rimIntensity));

    const nodeMat = new THREE.NodeMaterial();
    nodeMat.colorNode = origMat.color ? origMat.colorNode || origMat.color : new THREE.Color(0xffffff);
    nodeMat.roughnessNode = origMat.roughnessNode || float(0.5);
    nodeMat.metalnessNode = origMat.metalnessNode || float(0.4);
    nodeMat.emissiveNode = rimEmissive;
    nodeMat.transparent = true;
    nodeMat.opacity = origMat.opacity !== undefined ? origMat.opacity : 1.0;
    nodeMat.lights = true;

    mesh.material = nodeMat;
    // Dispose old material if not used elsewhere
    if (origMat.dispose) origMat.dispose();
  }

  // --- Entrance: weighted-settle animation ---
  const entranceTL = gsap.timeline({ paused: false });
  entranceTL.from(meshGroup.scale, {
    x: 0.9,
    y: 0.9,
    z: 0.9,
    duration: 0.9,
    ease: 'power4.out',
    overwrite: 'auto'
  })
  .to(meshGroup.scale, {
    x: 1.04,
    y: 1.04,
    z: 1.04,
    duration: 0.15,
    ease: 'none'
  }, '-=0.1')
  .to(meshGroup.scale, {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.25,
    ease: 'power4.out'
  });

  // --- Interaction handlers (hover + click) ---
  const hoverTL = gsap.timeline({ paused: true, reversed: true });
  hoverTL.to(meshGroup.position, {
    y: y + 0.15,
    duration: 0.3,
    ease: 'power3.out'
  });

  const handlers = {
    mouseenter: () => {
      hoverTL.play();
    },
    mouseleave: () => {
      hoverTL.reverse();
    },
    click: () => {
      if (ctx.emit) {
        ctx.emit('hub-journal.select', {});
      }
    }
  };
  meshGroup.userData.handlers = handlers;

  // --- Apply cinematic primitives ---
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach(primitive => {
      const applyPrim = ctx.primitives[primitive.name];
      if (applyPrim) {
        applyPrim(meshGroup, primitive.params);
      }
    });
  }

  // --- Cleanup ---
  meshGroup.userData.cleanup = () => {
    entranceTL.kill();
    hoverTL.kill();
    if (mesh.material) {
      mesh.material.dispose();
    }
    if (mesh.geometry) {
      mesh.geometry.dispose();
    }
    // Remove from parent
    if (meshGroup.parent) {
      meshGroup.parent.remove(meshGroup);
    }
  };

  return meshGroup;
}
